/* Lesson quizzes — batch 2 */
window.LQ=window.LQ||{};
Object.assign(window.LQ,{
"p3m1":[
 {id:"p3m1q1", q:"Two CPU-bound processes share one core: one at nice 0 (weight 1024), the other at nice 10 (weight 110). Roughly how does the scheduler split the core between them?", options:["About 50% each, because both are CPU-bound","About 75% and 25%","About 90% and 10%","100% for the nice 0 task until it finishes"], answer:2, why:"Each task's share is its weight over the total: 1024 / (1024 + 110) = 1024 / 1134, about 90%, leaving about 10%. The 75/25 split is the nice 0 versus nice 5 case; each nice step changes weight by about 1.25 times, so ten steps is much steeper."},
 {id:"p3m1q2", q:"strace on a failing program shows: openat(AT_FDCWD, \"/etc/app/app.conf\", O_RDONLY) = -1 EACCES (Permission denied). What does this line tell you?", options:["The file does not exist, so the path set in the program's configuration must be wrong","The permission check failed for this process; check the file's mode and its parent directories","The program crashed inside the kernel while it was opening the configuration file","strace itself blocked the open, because tracing through ptrace is invasive and slows the target process"], answer:1, why:"The kernel returned a negative result that libc turned into errno EACCES: the permission check failed for this process's UID and groups, on the file or a directory on its path. A missing file would return ENOENT instead, and nothing crashed."},
 {id:"p3m1q3", q:"A backup process shows STAT D in ps because it is waiting on an NFS server that has gone offline. You run kill -9 on it. What happens?", options:["It stays in D state until the I/O returns or fails, and still counts toward the load","It dies at once, because SIGKILL cannot be caught, blocked or ignored by any process","It becomes a zombie, which lingers until you also kill the parent backup process","It moves to state T (stopped) and waits there until it receives SIGCONT"], answer:0, why:"Uninterruptible sleep means the task cannot act on any signal until the kernel I/O completes, so even SIGKILL waits, and on Linux D tasks count toward load. 'SIGKILL cannot be caught' is true but beside the point: delivery itself is deferred until the I/O returns."},
 {id:"p3m1q4", q:"ps shows 40 processes in state Z, all with PPID 3120 (a custom job runner). An admin runs kill -9 on each zombie PID and nothing changes. What actually clears them?", options:["Repeat kill -9 as root, since zombies ignore signals sent by ordinary, unprivileged users","Reboot soon, because each zombie still holds its memory and the server is slowly leaking RAM","Send SIGCONT to each zombie so it can resume and finish exiting cleanly","Fix or restart the parent, PID 3120, so it calls wait and the zombies are reaped"], answer:3, why:"A zombie has already exited and holds only a PID slot, so there is nothing left to kill, as root or otherwise, and no memory to leak. It disappears when its parent calls wait, or when the parent exits and PID 1 adopts and reaps it."},
 {id:"p3m1q5", q:"A program allocates a 2 GiB buffer and writes to all of it. Its counters show about 524,000 minor page faults, no major faults, and it runs normally. What does this indicate?", options:["Memory corruption: each fault was an invalid access that the kernel had to repair silently","Normal demand paging: each new 4 KiB page was mapped from RAM on first touch","Heavy swapping: each fault had to read a page back in from the swap device","A bug in the program, because healthy programs never trigger page faults at all"], answer:1, why:"2 GiB is 524,288 pages of 4 KiB, and the kernel maps each one on first touch: a minor fault served from RAM. Major faults would mean disk reads from swap or uncached files. Faults are the normal mechanism of demand paging; only an unsatisfiable one becomes a segfault."}
],
"p3m2":[
 {id:"p3m2q1", q:"A small office installs a file server in May 2026 and wants free standard security updates through 2030 without a major-version upgrade. Which choice fits?", options:["Ubuntu 24.04 LTS","Ubuntu 26.04 LTS","The current Fedora release","Arch Linux"], answer:1, why:"Ubuntu LTS releases get five years of standard updates: 26.04 (April 2026) is covered until 2031. 24.04's standard support ends in 2029, so it would need Ubuntu Pro or an upgrade. Fedora releases last about thirteen months and Arch is rolling."},
 {id:"p3m2q2", q:"Which of these situations creates an obligation to make source code available under the license involved?", options:["Modifying a GPL-2.0 tool and running it only on your company's internal servers","Linking a closed-source program against glibc, which is LGPL","Using an MIT-licensed library in a closed-source product and keeping its notice","Selling routers whose firmware contains a modified GPL-2.0 Linux kernel"], answer:3, why:"Copyleft obligations attach to distribution: selling devices with a modified GPL kernel means offering that source. Modifying GPL software for internal use distributes nothing, the LGPL lets proprietary programs link to glibc, and MIT only requires keeping the notice."},
 {id:"p3m2q3", q:"You are writing a small tool, splicecheck, that colleagues will chain with grep and sort in pipelines. Which design follows the Unix philosophy best?", options:["Read input from stdin, write results to stdout, send errors to stderr, and exit non-zero on failure","Print results and error messages together on stdout, and always exit 0 so pipelines never stop","Write results to a fixed file, report.txt, so other tools know where to find them","Prompt the user for each input value interactively so mistakes are caught early"], answer:0, why:"Text on stdin and stdout lets the tool slot into any pipeline, stderr keeps errors out of the data stream, and a meaningful exit code lets scripts detect failure. Mixing errors into stdout corrupts the next stage's input, and always exiting 0 hides real failures."},
 {id:"p3m2q4", q:"In WSL2, npm install in /mnt/c/Users/tyler/app takes 90 seconds; the same project cloned to ~/app takes 15. What explains the difference?", options:["WSL2 translates every Linux system call into an equivalent Windows call, which is slow for npm's many calls","npm caches packages only under the Linux home directory, so in /mnt/c it downloads everything again","/mnt/c is reached over the 9P protocol across the VM boundary; ~ is on the VM's own ext4 disk","NTFS cannot hold more than a few thousand files per directory, so npm has to retry its writes"], answer:2, why:"WSL2 runs a real Linux kernel in a lightweight VM. Your home lives on an ext4 virtual disk, but /mnt/c is reached through a 9P file server on every file operation, which hurts tools that touch thousands of small files. Translating system calls was WSL1's design, not WSL2's."},
 {id:"p3m2q5", q:"A Bash script that uses only POSIX shell features and standard utilities, written on Ubuntu, runs unchanged on a Mac. What best explains this?", options:["macOS runs a Linux kernel underneath its desktop, so the same system calls are available","The GPL requires Apple to ship exactly the same GNU core utilities that Ubuntu ships","Bash compiles each script to portable bytecode that runs unchanged on any system","POSIX standardizes the shell and system interface, and macOS is a certified Unix"], answer:3, why:"POSIX (IEEE 1003) standardizes the shell and system-call interface, and macOS is a certified Unix with BSD roots, so conforming scripts port between them. macOS does not run the Linux kernel; the two share a standard, not code."}
],
"p3m3":[
 {id:"p3m3q1", q:"Your umask is 023. What modes do touch report.txt and mkdir reports produce? (Programs request 666 for files and 777 for directories.)", options:["File 643, directory 754","File 644, directory 644","File 640, directory 750","File 644, directory 754"], answer:3, why:"The new mode is requested AND NOT umask. 023 clears group write and other write and execute: 666 becomes 644 (the x bits were never requested) and 777 becomes 754. The tempting 643 comes from subtracting digits, which is not how a bit mask works."},
 {id:"p3m3q2", q:"budget.xlsx is -r--rw---- alice finance, and alice is a member of finance. She tries to save changes to the file. What happens?", options:["It fails: she owns the file, so only the owner triplet (r--) is ever checked","It succeeds: she gets the owner and group permissions combined","It succeeds, because the group triplet grants write and she is in finance","It fails, because the others triplet grants nothing"], answer:0, why:"The kernel uses only the first class that matches: owner, then group, then others. Alice is the owner, so only r-- applies and the write fails, even though the group triplet grants rw. Permissions are never combined across classes."},
 {id:"p3m3q3", q:"/data is drwxr-xr-x root root. Inside it, notes.txt is -rw-rw-rw- tyler tyler. Tyler, who is not root, runs rm /data/notes.txt. What happens?", options:["It succeeds, because tyler owns the file and its mode lets him write to it","It succeeds, because others have rw on the file, which lets any user delete it","It fails: deleting removes an entry from /data, which needs w and x on that directory","It fails, because only the owner of a directory may delete files from inside it"], answer:2, why:"Deleting removes a name from the directory, so the check is on /data, where tyler falls into others with only r-x. The file's own mode does not matter: a read-only file in a directory you can write to can be deleted, and this writable one cannot."},
 {id:"p3m3q4", q:"You ran setfacl -m u:www-data:rx /srv/site and the site worked. Later a colleague ran chmod 700 /srv/site, and getfacl now shows user:www-data:r-x #effective:---. Why did the site break?", options:["The named entry still reads r-x, so the problem must be the modes of the files inside","With an ACL present, chmod's group bits set the mask, and mask::--- caps www-data","chmod 700 made root the owner, so the existing ACL entries no longer apply","Named ACL entries apply only to files, so on the directory www-data falls into others (---)"], answer:1, why:"When an ACL exists, the group bits that ls shows and chmod changes are the mask, which caps every named entry and the group entry. chmod 700 set mask::---, so www-data's r-x is effectively nothing. Restore it with setfacl -m m::rx /srv/site."},
 {id:"p3m3q5", q:"A compiled service, /usr/local/bin/portald, must listen on port 443 but should run as an unprivileged user. Which approach follows least privilege?", options:["setcap cap_net_bind_service=+ep on the binary, then run it as its own user","chown it to root and chmod 4755 so it runs as root, which is safe for a compiled binary","Start it with sudo from a cron @reboot entry so only root ever launches it","chmod 777 the binary so the unprivileged user is allowed to start and bind it"], answer:0, why:"Capabilities split root's power; CAP_NET_BIND_SERVICE grants only the right to bind ports below 1024. Setuid root or sudo hands the program every root privilege, so any bug becomes full compromise, and 777 adds world write access without solving the port problem."}
],
"p3m4":[
 {id:"p3m4q1", q:"You run find / -name '*.conf' 2>&1 > found.txt as an ordinary user. Where do the 'Permission denied' messages go?", options:["To the terminal, while the matching paths go to found.txt","Into found.txt, together with the matching paths","To /dev/null, because 2>&1 discards errors","Nowhere, because find stops at the first error"], answer:0, why:"Redirections apply left to right. 2>&1 makes stderr a copy of what stdout is at that moment, the terminal; then > found.txt moves only stdout to the file. Write > found.txt 2>&1 (or &> found.txt) to capture both."},
 {id:"p3m4q2", q:"A script runs cat huge.log | head -1 followed by echo \"${PIPESTATUS[@]}\", which prints 141 0. What happened?", options:["cat failed with its own error code 141, which means the log file is corrupt or truncated","The pipe's 64 KiB buffer overflowed, so the kernel killed cat with an overflow error","head exited, so cat's next write raised SIGPIPE (13), and 128 + 13 = 141","cat ran out of memory loading the whole file before head was allowed to start"], answer:2, why:"When the reader exits, the writer's next write to the pipe raises SIGPIPE, which quietly kills it, and death by signal N shows as 128 + N. This is normal pipeline behaviour, not corruption. A full pipe never overflows; the kernel just blocks the writer."},
 {id:"p3m4q3", q:"To find the busiest client IPs you run awk '{print $1}' access.log | uniq -c | sort -rn | head -3. The output lists 198.51.100.4 three times, each with a small count. What is wrong?", options:["awk printed the wrong field; in nginx's log the client IP is field 7, not field 1","sort -rn compares the counts as text, which splits equal counts apart","head -3 runs before sort finishes, so it only sees partial output","uniq -c only merges adjacent duplicates, so sort must come before it"], answer:3, why:"uniq compares each line only with the previous one, so the same IP in separate runs is counted separately. Put sort before uniq -c to group identical lines. Field 1 is the client IP in nginx's log format; field 7 is the URL."},
 {id:"p3m4q4", q:"A script sets file=\"site survey.pdf\" and later runs rm $file without quotes. What arguments does rm receive?", options:["One argument: site survey.pdf","Two arguments: site and survey.pdf","The literal text $file, because arguments are not expanded","An empty argument, because the space ends the variable"], answer:1, why:"Parameter expansion happens before word splitting, and an unquoted result is split on spaces, so rm receives two names and may delete an unrelated file called site. rm \"$file\" keeps one word, because double quotes allow substitution but stop splitting and globbing."},
 {id:"p3m4q5", q:"In nginx's combined log format, field 9 is the status code and field 10 the response size in bytes. Which command totals the bytes served in 404 responses only?", options:["grep -c 404 access.log","grep 404 access.log | awk '{s+=$10} END {print s}'","awk '$9==404 {s+=$10} END {print s}' access.log","awk '{s+=$10} END {print s}' access.log | grep 404"], answer:2, why:"awk tests field 9 exactly and adds field 10, printing once in the END block. grep 404 matches those digits anywhere on a line, including URLs and sizes, so it can count wrong lines; grep -c counts lines rather than bytes, and grepping a final total is meaningless."}
],
"p3m5":[
 {id:"p3m5q1", q:"A nightly job's wrapper logs that the program ended with exit status 139, and nothing in the program calls exit(139). What happened?", options:["It was killed by SIGKILL, most likely the OOM killer","It was killed by signal 11, SIGSEGV: an invalid memory access","Someone pressed Ctrl-C in its terminal (SIGINT)","systemctl stop sent SIGTERM and it shut down cleanly"], answer:1, why:"A process killed by signal N exits with 128 + N, and 139 minus 128 is 11, SIGSEGV. SIGKILL from the OOM killer would show 137, Ctrl-C 130 and SIGTERM 143. Look for the kernel's segfault line with journalctl -k or a core dump."},
 {id:"p3m5q2", q:"app.service has After=postgresql.service but no Wants= or Requires=. PostgreSQL is installed but not enabled. After a reboot the app cannot reach its database. Why?", options:["After= only orders startup; it never pulled PostgreSQL in, so nothing started it","After= did start PostgreSQL but did not wait for it to be ready, so the app raced ahead","systemd ignores After= unless the unit also sets Type=notify for readiness","The unit needed another systemctl daemon-reload after the reboot to load its dependencies"], answer:0, why:"Ordering and dependencies are separate in systemd. After= only says 'if both are starting, start me later' and pulls nothing in. Add Wants= or Requires=postgresql.service alongside the After=, or enable PostgreSQL. After= does make the app wait for a unit that is starting."},
 {id:"p3m5q3", q:"After a bad config edit, systemctl status worker shows Active: failed (Result: start-limit-hit). What is the right sequence?", options:["Raise StartLimitBurst to 100 in the unit so systemd keeps retrying until the worker comes up","Edit /usr/lib/systemd/system/worker.service to remove Restart=on-failure","Check journalctl -u worker, fix the config, then reset-failed and start it","Run kill -9 on the worker's PID so that systemd forgets the recorded failures"], answer:2, why:"start-limit-hit means more than five starts within ten seconds, so systemd stopped trying. Find the cause in the journal, fix it, then clear the counter with reset-failed. Raising the limit only crash-loops faster, and vendor unit files should never be edited; use drop-ins."},
 {id:"p3m5q4", q:"This crontab line never produces a backup, though the command works in a shell: 0 3 * * * tar -czf /backup/etc-$(date +%F).tgz /etc. The cron mail reports a shell syntax error. What is the cause?", options:["The line is missing a user field between the schedule and the command","tar is missing from cron's minimal PATH","$(...) command substitution is not allowed in a crontab","% is special in a crontab line (it becomes a newline), so it must be written \\%"], answer:3, why:"cron turns an unescaped % into a newline and passes the rest as stdin, so the shell sees an unterminated $(date + and reports a syntax error. Write date +\\%F. tar lives in /usr/bin, which cron's default PATH includes, and a user crontab has no user field."},
 {id:"p3m5q5", q:"A server crashed overnight. After it reboots, journalctl -b -1 reports that there is no previous boot to show. What is the most likely reason?", options:["The journal lived only in /run/log/journal, in RAM; make it persistent","The crash corrupted the journal files, which always happens after a kernel panic or power loss","journalctl needs -k added to show anything from an earlier boot","logrotate deleted the old binary journal during boot, as it does by default"], answer:0, why:"Without /var/log/journal or Storage=persistent, journald keeps logs in /run/log/journal, which lives in RAM and vanishes at reboot. Make the journal persistent so the next crash leaves evidence. -k only filters to kernel messages, and logrotate handles text logs, not the journal."}
],
"p3m6":[
 {id:"p3m6q1", q:"On an Ubuntu cloud VM you set PasswordAuthentication no near the end of /etc/ssh/sshd_config and restarted ssh, but password logins still work. What is the best next step?", options:["Reboot the server, because sshd only rereads its configuration at boot","Add PasswordAuthentication no a second time at the end so the later value wins","Check sudo sshd -T for the effective value, and look for an override in sshd_config.d/","Delete ~/.ssh/known_hosts on your PC so the client picks up the server's new setting"], answer:2, why:"sshd keeps the first value it reads for each setting, and the main file includes sshd_config.d/*.conf at the top, so a cloud-init file saying yes wins. sshd -T prints the effective value. Repeating the line further down the same file still loses to the earlier include."},
 {id:"p3m6q2", q:"/etc/shadow contains alice:!$6$Rk3v...$Hq9...:20380:0:99999:7::: What can you conclude about this account?", options:["The hash is yescrypt and alice can log in with her password","The account has no password, so anyone can log in as alice","The hash is obsolete MD5, which is why the account was disabled","The hash is SHA-512-crypt, and the leading ! means her password is locked"], answer:3, why:"$6$ marks SHA-512-crypt ($y$ is yescrypt, $1$ obsolete MD5), and a leading ! means the password is locked, for example by passwd -l. A * in the hash field would mean no password login at all; ! is a lock placed in front of an existing hash."},
 {id:"p3m6q3", q:"On a RHEL server you run firewall-cmd --add-service=https and HTTPS starts working. After the next reboot it is blocked again. Why?", options:["firewalld rules added from the command line expire after 24 hours unless they are renewed","It changed only the runtime configuration; it needed --permanent and a reload","SELinux resets the firewall to its default policy at every boot","HTTPS also needs port 80 open, or the rule is dropped at the next reboot"], answer:1, why:"firewalld keeps runtime and permanent configurations separately. Without --permanent the change lives only until the next reload or reboot. Repeat it with --permanent and run firewall-cmd --reload. No timer expires firewalld rules, and HTTPS does not depend on port 80."},
 {id:"p3m6q4", q:"From your own server, ping -M do -s 1393 1.1.1.1 fails, but ping -M do -s 1392 1.1.1.1 succeeds. What is the path MTU?", options:["1420","1412","1400","1392"], answer:0, why:"-s sets only the ICMP data size; each packet adds an 8-byte ICMP header and a 20-byte IP header, so 1392 + 28 = 1420 bytes pass with don't-fragment set. 1392 forgets both headers, and 1400 or 1412 counts only one. 1420 is typical of a VPN tunnel."},
 {id:"p3m6q5", q:"A server has ufw default deny incoming and allows only 22 and 443. A colleague runs docker run -p 8080:80 nginx, and port 8080 is reachable from the internet. Why?", options:["ufw filters only UDP by default, and Docker publishes container ports over TCP","ufw needs a reboot before a default deny incoming policy actually takes effect","ufw blocks only privileged ports below 1024, and 8080 is above that range, so it passes","Docker inserts its own netfilter rules for published ports ahead of ufw's rules"], answer:3, why:"Docker writes its own nftables/iptables rules for published ports, evaluated before ufw's, so ufw never sees those packets. Publish as -p 127.0.0.1:8080:80 if only local access is needed, and verify from another machine rather than trusting ufw status."}
],
"p3m7":[
 {id:"p3m7q1", q:"f=/home/tyler/logs/app.2026-10.log.gz; name=${f##*/}. What does echo \"${name%%.*}\" print?", options:["app","app.2026-10.log","app.2026-10.log.gz","/home/tyler/logs/app"], answer:0, why:"${f##*/} deletes the longest match of */ from the front, leaving app.2026-10.log.gz. %%.* then deletes the longest match of .* from the end, which starts at the first dot, leaving app. A single % would delete only the shortest match, .gz."},
 {id:"p3m7q2", q:"A script begins with set -euo pipefail. Line 10 is grep -q ERROR app.log && echo \"errors found\", and app.log contains no ERROR. What happens next?", options:["The script exits at line 10 with status 1, because set -e stops at any failing command","It continues to line 11: set -e is suspended on the left of &&","set -u aborts the script, because grep printed nothing and left an empty value","pipefail makes the script exit, because grep failed inside the && list"], answer:1, why:"grep returns 1, but set -e is deliberately suspended for commands on the left of && and ||, and in if and while conditions, so execution continues. There is no pipeline for pipefail to act on, and set -u concerns unset variables, not empty output."},
 {id:"p3m7q3", q:"A backup script works in your terminal but fails from cron with 'pg_dump: command not found' (status 127). You added /usr/lib/postgresql/16/bin to PATH in ~/.bashrc. Why does cron fail?", options:["cron reads ~/.bashrc only for jobs scheduled with @reboot, not for timed jobs","Status 127 means pg_dump was found but is missing its execute bit for the cron user","cron runs every job as root, and root is not allowed to run PostgreSQL client tools","cron's non-interactive shell reads none of your startup files, so PATH lacks that directory"], answer:3, why:"Cron, systemd and scripts run non-interactive shells that read neither ~/.bashrc nor ~/.profile, so they get a minimal PATH. Status 127 means command not found; a missing execute bit would give 126. Use the absolute path, or set PATH inside the script."},
 {id:"p3m7q4", q:"setproxy.sh contains export HTTPS_PROXY=http://10.0.0.5:3128. You run ./setproxy.sh, then echo $HTTPS_PROXY prints nothing. What fixes it?", options:["Add #!/usr/bin/env bash as the first line so the export is kept afterwards","Run it with sudo, which is allowed to change the environment of your login shell","Run source setproxy.sh (or . setproxy.sh) so it runs in the current shell","chmod +x setproxy.sh so the export becomes permanent"], answer:2, why:"./setproxy.sh runs in a child process with its own copy of the environment; the export vanishes when it exits, because a child can never change its parent's variables. source runs the lines in your current shell. sudo starts yet another process, so it cannot help."},
 {id:"p3m7q5", q:"./run.sh on a USB drive mounted at /mnt/usb fails with 'Permission denied' and $? is 126. ls -l shows -rwxr-xr-x tyler tyler run.sh. What is the most likely cause?", options:["bash itself is not on PATH, and status 126 means the command was not found","The file system is mounted noexec, so nothing on it may execute","The script must be owned by root before the kernel will execute it from a USB drive","The script has a syntax error on its first line"], answer:1, why:"126 means found but not executable: either the execute bit is missing or the mount forbids execution. The mode grants x to everyone, which leaves the noexec mount option. 127 would mean command not found, and a syntax error produces a bash error message, not Permission denied."}
],
"p3m8":[
 {id:"p3m8q1", q:"How many inodes does a new 200 GiB ext4 file system get with the default ratio of one inode per 16 KiB?", options:["52,428,800","12,500,000","3,276,800","13,107,200"], answer:3, why:"200 × 2^30 bytes divided by 2^14 bytes per inode is 200 × 65,536 = 13,107,200. The count is fixed at mkfs time, so millions of tiny files can exhaust it while space remains. 12,500,000 mixes decimal and binary units; 52,428,800 assumes one inode per 4 KiB."},
 {id:"p3m8q2", q:"You deleted a 30 GB debug log, but df -h /var still shows 100% while du -sh /var reports only 9 GB. What explains this, and what is the fix?", options:["df caches its figures, so wait for the next hourly refresh before the freed 30 GB appears","rm moved the file to a hidden trash folder; empty /var/.Trash to release the space","A running process still holds the deleted file open; find it with lsof +L1 and restart it","The inode table is damaged by the delete; run e2fsck on the mounted /var to repair it"], answer:2, why:"rm removes a name; the blocks are freed only when no names remain and no process holds the file open. lsof +L1 lists such files. rm has no trash, and e2fsck must never run on a mounted file system. Next time, empty a live log with truncate -s 0."},
 {id:"p3m8q3", q:"You run echo hi > a.txt; ln a.txt h.txt; ln -s a.txt s.txt; rm a.txt. What do cat h.txt and cat s.txt do now?", options:["h.txt prints hi; s.txt fails with No such file or directory","Both print hi, because both links keep the data alive","h.txt fails; s.txt prints hi, because symlinks cache their target","Both fail, because the data was deleted along with a.txt"], answer:0, why:"A hard link is a second name for the same inode, so the data survives until the last name goes. A symlink is a separate small file containing the path a.txt, which no longer exists, so it dangles. rm removed one name and decremented the link count."},
 {id:"p3m8q4", q:"The volume group behind /dev/data/web uses 4 MiB extents. You run lvextend -r -L +36G /dev/data/web while it is mounted. How many extents are added, and what does -r do?", options:["36,864 extents; -r grows the file system online","9,216 extents; -r grows the mounted file system in the same command","9,216 extents; -r reboots into rescue mode to resize safely","144 extents; -r keeps the volume read-only during the resize"], answer:1, why:"36 GiB is 36 × 1,024 = 36,864 MiB; divided by 4 MiB per extent that is 9,216 extents. With -r, lvextend immediately runs the file system's grow tool (xfs_growfs or resize2fs) while it stays mounted. 36,864 forgets to divide by the extent size."},
 {id:"p3m8q5", q:"After a kernel update, a server stops at 'Kernel panic - not syncing: VFS: Unable to mount root fs'. Which link of the boot chain broke, and what is the rescue?", options:["The UEFI boot entries; recreate them with efibootmgr from a live USB stick","An /etc/fstab line; fix it from the emergency shell, run mount -a, and reboot again","The kernel or its initramfs; boot the old kernel from GRUB, then rebuild the initramfs","grub.cfg; edit it by hand so that it points at the new kernel and initramfs"], answer:2, why:"The kernel started but could not find the real root, which usually means the new initramfs lacks storage or LVM drivers. The previous kernel boots from GRUB; then regenerate the initramfs. An fstab error appears later, as systemd's emergency mode, not as a kernel panic."}
],
"p3m9":[
 {id:"p3m9q1", q:"You run systemctl set-property worker.service CPUQuota=250% MemoryMax=2G. What do the service's cgroup v2 files cpu.max and memory.max then contain?", options:["cpu.max 25000 100000; memory.max 2000000000","cpu.max 250000 100000; memory.max 2147483648","cpu.max 250 100; memory.max 2147483648","cpu.max 100000 250000; memory.max 2097152"], answer:1, why:"cpu.max holds quota and period in microseconds: 250% means 250 ms of CPU per 100 ms of wall time, 2.5 CPUs, so 250000 100000. MemoryMax=2G is 2 × 2^30 = 2,147,483,648 bytes. 2,000,000,000 uses decimal gigabytes, and swapping quota and period inverts the limit."},
 {id:"p3m9q2", q:"A minimal container image on your own server has no ip or ss commands. You need to see the container's interfaces and listening sockets. Which approach fits?", options:["Find its PID, then run nsenter -t PID -n ip addr (and ss -tlnp)","Restart it with --privileged so it can see and run the host's networking tools","Run ip addr on the host, since containers share the host's network namespace","Run docker logs on it, which prints its interfaces and sockets at startup"], answer:0, why:"nsenter joins an existing namespace, so host tools run with the container's view of the network and nothing in the container changes. --privileged strips most isolation and is never a debugging shortcut, and containers normally have their own net namespace, so host ip addr shows the host."},
 {id:"p3m9q3", q:"/etc/subuid contains tyler:200000:65536. In tyler's rootless Podman container, a process runs as UID 33 (www-data). Which host UID does it really run as?", options:["33","1033","200033","200032"], answer:3, why:"Container root maps to tyler's own UID, and container UIDs 1 to 65536 map to host UIDs 200000 to 265535, so UID n becomes 200000 + n - 1 = 200032. 200033 forgets that the range starts at container UID 1; 33 would be real host www-data, with no user namespace."},
 {id:"p3m9q4", q:"Inside a running container you edit /etc/app/settings.yaml to fix a bug. Later you docker rm the container and start a new one from the same image. The fix is gone. Why?", options:["Docker reverts edits under /etc in every running container hourly, to protect the image","The edit was saved into the image itself, but docker rm cleared the local image cache","The write went to the container's own writable layer, deleted by docker rm","The new container runs on a different kernel, which ignores the edited file"], answer:2, why:"overlayfs stacks read-only image layers under a fresh writable upper directory per container. Editing a file copies it up into that layer, and docker rm deletes the layer. Put configuration in the image build, a volume or a bind mount. All containers share the host kernel."},
 {id:"p3m9q5", q:"A 4-vCPU cloud VM shows load average 8. vmstat 1 reports r=9, b=0, us=18, sy=4, id=0, wa=0, st=78. Where is the bottleneck?", options:["The hypervisor is giving this VM's CPU time to other guests: steal time at 78%","The disk, because the nine waiting tasks are queued behind slow storage I/O","One application thread is saturating a single core while the rest sit idle","Memory pressure, with the system thrashing swap and stalling every task"], answer:0, why:"st is CPU time stolen by the hypervisor: at 78% the vCPUs are runnable but not getting real CPU. Nine runnable tasks with none blocked and wa at 0 rules out the disk. The cure lies with the provider or a different instance, not inside the guest."}
]
});
Object.assign(window.LQ,{
"p4m1":[
 {id:"p4m1q1", q:"What does print(-9 // 4, -9 % 4) output in Python 3?", options:["-2 -1","-2 1","-3 3","-3 -3"], answer:2, why:"// floors toward negative infinity: -9 / 4 is -2.25, so -9 // 4 is -3. The remainder keeps a == (a // b) * b + a % b, and -9 = (-3)(4) + 3. The answer -2 -1 is C and Java behaviour, which truncates toward zero."},
 {id:"p4m1q2", q:"What does print(-3 ** 2, 2 ** 2 ** 3, 10 - 4 % 3) output?", options:["9 64 0","-9 64 9","9 256 9","-9 256 9"], answer:3, why:"** binds tighter than unary minus, so -3 ** 2 is -(3 ** 2) = -9. ** is right-associative, so 2 ** 2 ** 3 is 2 ** 8 = 256. % binds tighter than -, so 10 - 1 = 9. Evaluating ** left to right gives the tempting 64."},
 {id:"p4m1q3", q:"What does print('' or 'guest', 0 and 5, [] or 0) output?", options:["guest False False","guest 0 0","True 5 0","guest 5 []"], answer:1, why:"and and or return one of their operands, not a bool. '' is falsy, so or returns 'guest'; 0 is falsy, so and stops and returns 0; [] is falsy, so or returns its right operand, 0. Expecting True or False is the common mistake."},
 {id:"p4m1q4", q:"total = 0.0, then for _ in range(10): total += 0.1, then print(total == 1.0). What prints, and what is the right fix?", options:["False; use math.isclose(total, 1.0), or count in integer tenths instead","True; ten additions of 0.1 make exactly 1.0, so == works here","False; write total is 1.0 instead, which compares the exact value","It raises FloatingPointError on the tenth addition"], answer:0, why:"0.1 has no exact binary representation, so the sum is 0.9999999999999999 and == is False. math.isclose compares within a tolerance, and integer units avoid the error entirely. is compares object identity, which makes the comparison worse, not better."},
 {id:"p4m1q5", q:"Which of these conditions is a latent bug that may pass in testing and fail later?", options:["if result is None:","if retries == 300:","if 0 < retries <= 300:","if retries is 300:"], answer:3, why:"is compares identity. CPython caches only the ints from -5 to 256, so two equal 300s can be different objects and the test can be False when the values match; Python even warns about is with a literal. Use == for values and keep is for None."}
],
"p4m2":[
 {id:"p4m2q1", q:"How many times does the body of for i in range(3, 20, 4): run, and what is the last value of i?", options:["5 times, last value 19","4 times, last value 15","5 times, last value 20","17 times, last value 19"], answer:0, why:"A range has ceil((stop - start) / step) values: ceil(17 / 4) = 5, namely 3, 7, 11, 15 and 19. The stop value 20 is excluded but 19 is below it. Dividing without rounding up gives 4, a classic off-by-one."},
 {id:"p4m2q2", q:"Code: if loss > 0.1: status = 'warn' / elif loss > 0.5: status = 'fail' / else: status = 'ok'. What is status for loss = 0.8, and what is the bug?", options:["fail; the chain picks the most specific matching branch, so it works as written","warn and then fail; every true branch runs in turn, so the last one wins","warn; 0.8 matches the 0.1 test first, so fail is unreachable","ok; 0.8 matches neither branch exactly, so the else runs"], answer:2, why:"Only the first truthy branch of an if/elif chain runs. 0.8 > 0.1 is True, so status becomes warn and the elif is skipped; any value above 0.5 is also above 0.1, which makes fail unreachable. Test the highest threshold first."},
 {id:"p4m2q3", q:"A for loop over [4, 9, 12] has the body if n % 3 == 0: print('hit', n); break, and an else: print('none') clause attached to the loop itself. What prints?", options:["hit 9, then none","hit 9","hit 9, then hit 12","none"], answer:1, why:"4 is not a multiple of 3; 9 is, so the loop prints hit 9 and breaks. A loop's else runs only when the loop finishes without break, so none is skipped, and 12 is never reached because break exits immediately."},
 {id:"p4m2q4", q:"pairs = zip(['a', 'b', 'c'], [1, 2, 3]); then print(len(list(pairs)), len(list(pairs))). What prints?", options:["3 3","6 6","TypeError: object of type 'zip' has no len()","3 0"], answer:3, why:"zip returns a single-use iterator. The first list(pairs) consumes all three pairs; the second finds it exhausted and builds an empty list. len is applied to the lists, not the zip object, so there is no TypeError. Use list(zip(...)) once for two passes."},
 {id:"p4m2q5", q:"Which condition is equivalent to not (loss <= 0.3 and clean)?", options:["loss > 0.3 and not clean","loss >= 0.3 or not clean","loss > 0.3 or not clean","not loss <= 0.3 and clean"], answer:2, why:"De Morgan: not (a and b) equals (not a) or (not b). not (loss <= 0.3) is loss > 0.3, so the result is loss > 0.3 or not clean. Keeping and is the classic slip, and >= would wrongly reject a splice of exactly 0.3."}
],
"p4m3":[
 {id:"p4m3q1", q:"def update(cfg, n): has the body cfg['retries'] = n; cfg = {'retries': 0}; n += 1. After c = {'retries': 1}; k = 5; update(c, k), what does print(c, k) show?", options:["{'retries': 0} 6","{'retries': 1} 5","{'retries': 5} 6","{'retries': 5} 5"], answer:3, why:"Python passes references. Mutating cfg['retries'] changes the caller's dict to 5; rebinding cfg to a new dict and n += 1 only move local names, so the caller sees neither. That is call by sharing: mutation is visible, rebinding is not."},
 {id:"p4m3q2", q:"handlers = []; for name in ['ana', 'bo', 'cy']: handlers.append(lambda: name.upper()). What does print([h() for h in handlers]) output?", options:["['ANA', 'BO', 'CY']","['CY', 'CY', 'CY']","['ANA', 'ANA', 'ANA']","NameError, because name no longer exists after the loop"], answer:1, why:"Each lambda captures the variable name, not its value at creation time, so all three read its final value, 'cy'. The loop variable still exists after the loop, so there is no NameError. Freeze each value with a default: lambda name=name: name.upper()."},
 {id:"p4m3q3", q:"def log(msg, *parts, level='INFO', **meta): return f'{level} {msg} {parts} {meta}'. What does log('disk', 90, 'WARN') return?", options:["INFO disk (90, 'WARN') {}","WARN disk (90,) {}","INFO disk [90, 'WARN'] {}","TypeError: log() takes 1 positional argument but 3 were given"], answer:0, why:"Parameters after *parts are keyword-only, so level can be set only as level='WARN'. The extra positional values 90 and 'WARN' are collected into the tuple parts. *args always builds a tuple, not a list, and accepts any number of extras."},
 {id:"p4m3q4", q:"make_acc(start) sets total = start and returns an inner add(x) that does nonlocal total; total += x; return total. After a = make_acc(10); b = make_acc(0); a(5); b(1), what does print(a(5), b(1)) output?", options:["15 1","20 22","20 2","UnboundLocalError"], answer:2, why:"Each call to make_acc creates its own total, and each closure keeps its own alive. a goes 10, 15, 20 and b goes 0, 1, 2; they never share, so 22 is wrong. nonlocal makes total += x legal, so there is no UnboundLocalError."},
 {id:"p4m3q5", q:"A script sets sum = 0 at module level and adds to it in a loop. Later, total = sum([1, 2, 3]) raises TypeError: 'int' object is not callable. Why?", options:["sum() accepts only tuples or sets, not lists, and reports it as a TypeError","The module-level sum hides the built-in: LEGB checks Global before Built-in names","Built-in functions cannot be called once a loop has modified any global name","The list must first be converted with list() before the built-in can sum it"], answer:1, why:"Names resolve Local, Enclosing, Global, Built-in, and the first match wins. Assigning sum at module level puts an int in the global scope, hiding the built-in sum. Rename the variable, for example to running_total, and the built-in is reachable again."}
],
"p4m4":[
 {id:"p4m4q1", q:"board = [['.'] * 2] * 3; board[1][0] = 'X'; print(board). What prints?", options:["[['.', '.'], ['X', '.'], ['.', '.']]","[['X', '.'], ['X', '.'], ['X', '.']]","[['X', 'X'], ['.', '.'], ['.', '.']]","TypeError: can't multiply a nested list"], answer:1, why:"The outer * 3 copies the reference to one inner list three times, so all three rows are the same object and a change through any row shows in every row. Build independent rows with [['.'] * 2 for _ in range(3)]."},
 {id:"p4m4q2", q:"Which of these dictionary assignments raises TypeError?", options:["d[(3, 'a')] = 1","d[frozenset({1, 2})] = 1","d[True] = 1","d[(1, [2, 3])] = 1"], answer:3, why:"A key must be hashable, with a hash that can never change. A tuple is hashable only if everything in it is, and this one contains a list: TypeError: unhashable type: 'list'. A frozenset is immutable and True is an int, so both are valid keys."},
 {id:"p4m4q3", q:"a = [[1, 2], [3]]; b = a.copy(); b[0].append(9); b.append([7]). What is a now?", options:["[[1, 2], [3]]","[[1, 2, 9], [3], [7]]","[[1, 2, 9], [3]]","[[1, 2], [3], [7]]"], answer:2, why:"copy() is shallow: b is a new outer list holding the same inner lists. Appending 9 to b[0] mutates an inner list that a shares, but appending [7] changes only b's outer list. Use copy.deepcopy for fully independent nested data."},
 {id:"p4m4q4", q:"How does peak memory compare between sum(x * x for x in range(10**7)) and sum([x * x for x in range(10**7)])?", options:["The list holds 10 million pointers (about 80 MB) plus ints; the generator only about 200 bytes","They are the same, because Python compiles both forms into the same loop before sum runs","The generator uses more, because it caches every value it yields for reuse","The list version is smaller, because a list stores its ints as raw C integers in one block"], answer:0, why:"The brackets build the whole list before sum starts: 10^7 pointers at 8 bytes is 80 MB, and each int is a separate heap object. The parentheses make a generator that yields one value at a time. Lists hold pointers, not raw C integers."},
 {id:"p4m4q5", q:"A list grows to a million items through append, and occasionally an append copies every pointer into a bigger array. Why is append still called amortized O(1)?", options:["CPython quietly switches the list to a hash table once it passes about 100,000 items","Copying pointers costs nothing on a 64-bit CPU, so a resize is effectively free","Big-O simply ignores any operation that happens less than half the time, so resizes don't count","Capacity grows proportionally, so rare resizes average out to constant work per append"], answer:3, why:"Capacity grows by a proportion each time, so most appends just fill a spare slot, and the copies made by the rare resizes add up to a constant multiple of n. Spread over n appends, that is constant per append. Copying is not free, only rare."}
],
"p4m5":[
 {id:"p4m5q1", q:"s = 'naïve €5'. What does print(len(s), len(s.encode('utf-8'))) output?", options:["8 8","8 10","8 11","11 11"], answer:2, why:"len counts code points: 8. In UTF-8 the six ASCII characters take one byte each, ï (U+00EF) takes two and € (U+20AC) takes three, so 6 + 2 + 3 = 11. Assuming one byte per character gives 8; forgetting that € needs three gives 10."},
 {id:"p4m5q2", q:"try: v = settings[key] / except LookupError: print('missing') / except KeyError: print('no key'). With settings = {} and key = 'x', what prints, and what is wrong with the code?", options:["missing; LookupError is KeyError's parent and matches first","no key; Python always picks the most specific matching clause, wherever it appears","missing, then no key; every clause whose class matches runs in order","Nothing; LookupError covers only lists and tuples, not dictionaries"], answer:0, why:"except clauses are tried top to bottom, and the first whose class matches, including a parent class, handles the exception. KeyError derives from LookupError, so the first clause catches it and the second is dead code. Put specific classes before general ones."},
 {id:"p4m5q3", q:"def f(s): try: n = int(s) / except ValueError: return 'bad' / else: return f'ok {n}' / finally: print('done', end=' '). What does print(f('x')) display?", options:["bad done","bad","done ok x","done bad"], answer:3, why:"int('x') raises ValueError, so the except clause returns 'bad'. finally runs on the way out of the function, printing done before the caller's print receives and shows the return value. else runs only when the try block raised nothing."},
 {id:"p4m5q4", q:"What does sorted(['beta', 'Alpha', 'alpha', 'Beta']) return?", options:["['Alpha', 'alpha', 'Beta', 'beta']","['Alpha', 'Beta', 'alpha', 'beta']","['alpha', 'Alpha', 'beta', 'Beta']","['Alpha', 'alpha', 'beta', 'Beta']"], answer:1, why:"Strings compare by code point, and every uppercase letter (A is 65) comes before every lowercase one (a is 97), so both capitalized words sort first. For dictionary order use key=str.lower, which gives ['Alpha', 'alpha', 'beta', 'Beta'] because the sort is stable."},
 {id:"p4m5q5", q:"A report written on Linux with open('r.txt', 'w') is read on Windows with Python 3.12 using open('r.txt'), and café appears as cafÃ©. What is the cause and the fix?", options:["The Windows default codec (cp1252) misread the UTF-8 bytes; open with encoding='utf-8'","The file was corrupted in transfer; rewrite it and read it back in binary mode to protect it","Windows newline translation altered the é while converting \\n to \\r\\n on reading","Python 3.12 cannot read non-ASCII text files on Windows without an extra codec"], answer:0, why:"Before Python 3.15 the text-mode default codec came from the OS locale. The UTF-8 bytes c3 a9 decoded as cp1252 become Ã and ©: mojibake. Passing encoding='utf-8' on both sides makes the code portable. Newline translation affects only \\r\\n, never letters."}
],
"p4m6":[
 {id:"p4m6q1", q:"Merge sort on 1,048,576 (2^20) items: how many levels of halving are there, and roughly how many element moves in total?", options:["20 levels, about 2.1 × 10^7 moves","20 levels, about 5.5 × 10^11 moves","1,048,576 levels, about 10^12 moves","10 levels, about 10^7 moves"], answer:0, why:"Halving 2^20 items down to single elements takes log2 n = 20 levels, and the merges at each level touch every element once, so 2^20 × 20 is about 2.1 × 10^7. About 5.5 × 10^11 is n²/2, the work of selection sort on the same data."},
 {id:"p4m6q2", q:"A binary search uses while lo < hi: instead of while lo <= hi:, otherwise unchanged. What does it return for items = [3, 8, 11] and target = 11?", options:["2, the correct index, because the loop still reaches the last element","-1, since the last range (lo == hi) is never checked","It loops forever, because lo never moves past mid","1, because mid rounds down and the loop returns the nearest index"], answer:1, why:"After the first probe (mid = 1, value 8) lo becomes 2 and hi is 2, so items[2] is the only candidate, but lo < hi is False and the loop exits without checking it. Writing lo = mid without + 1 is the variant that can loop forever."},
 {id:"p4m6q3", q:"people = [('lee', 3), ('bo', 1), ('kim', 3), ('ana', 1)]. What does sorted(people, key=lambda p: p[1]) return?", options:["[('ana', 1), ('bo', 1), ('kim', 3), ('lee', 3)]","[('ana', 1), ('bo', 1), ('lee', 3), ('kim', 3)]","[('bo', 1), ('ana', 1), ('lee', 3), ('kim', 3)]","[('bo', 1), ('ana', 1), ('kim', 3), ('lee', 3)]"], answer:2, why:"The key compares only the number, and Timsort is stable: items with equal keys keep their input order. bo came before ana, and lee before kim, so they stay that way. Alphabetical ties would need a tuple key such as (p[1], p[0])."},
 {id:"p4m6q4", q:"def total(nums, i=0, acc=0): return acc if i == len(nums) else total(nums, i + 1, acc + nums[i]). What happens when you call total on a list of 5,000 numbers?", options:["It returns the sum; the recursive call is the last action, so CPython reuses the frame","It returns the sum slowly, because each call copies the list","It returns 0, because acc is reset to its default on every call","It raises RecursionError: CPython creates a frame for every call and the default limit is 1,000"], answer:3, why:"CPython never eliminates tail calls, so 5,000 levels need about 5,000 frames, far beyond the default recursion limit of 1,000. Passing an index avoids list copies, so slicing cost is not the issue, and defaults apply only when an argument is omitted."},
 {id:"p4m6q5", q:"You receive an unsorted list of 2 million readings and must check, just once, whether one value appears in it. Which approach does the least work?", options:["Sort it, then binary search, because O(log n) is always faster","A single linear scan with x in readings: O(n)","Build a set from it first, then test membership","Sort it with selection sort, then binary search"], answer:1, why:"Sorting costs O(n log n), about 2 × 10^6 × 21 steps, before binary search can help, and building a set also touches every item while hashing each one. For a single lookup one O(n) scan does the least work; sorting pays off only across many lookups."}
],
"p4m7":[
 {id:"p4m7q1", q:"class A defines who() returning 'A'. class B(A): pass. class C(A) defines who() returning 'C'. class D(B, C): pass. What does D().who() return?", options:["'A'","AttributeError, because B does not define who","TypeError, because B and C both inherit from A","'C'"], answer:3, why:"Python linearizes the classes with C3: D.__mro__ is D, B, C, A, object. B does not define who, so lookup moves to C, which does. A depth-first search through B to A would wrongly give 'A'; C3 places A after both of its subclasses."},
 {id:"p4m7q2", q:"Your project folder has a file you named csv.py next to report.py. In report.py, import csv followed by csv.reader(f) raises AttributeError: module 'csv' has no attribute 'reader'. Why?", options:["The csv module was removed from the standard library in 3.14 and is now on PyPI","csv.reader must be imported with from csv import reader before it can be used","The script's directory comes first on sys.path, so your own csv.py was imported instead","The file f was opened in binary mode, which hides the reader attribute"], answer:2, why:"import searches sys.path in order, starting with the script's own directory, so your csv.py shadows the standard module. Rename it and delete its __pycache__ entry. The same mechanism lets an untrusted file placed beside a script hijack an import."},
 {id:"p4m7q3", q:"tools.py has print('loading') at the top and ends with if __name__ == '__main__': main(). app.py runs import tools, and a helper module that app.py imports also runs import tools. Running python app.py prints loading how many times, and does main() run?", options:["Twice; main() runs once","Once; main() does not run","Once; main() runs once","Twice; main() does not run"], answer:1, why:"A module's top-level code runs once per process; the second import finds tools in sys.modules and only binds the name. When imported, __name__ is 'tools', not '__main__', so the guard skips main(). It runs only with python tools.py."},
 {id:"p4m7q4", q:"class Cfg: limit = 10. Then a, b = Cfg(), Cfg(); a.limit = 5; Cfg.limit = 20. What does print(a.limit, b.limit) output?", options:["5 20","5 5","20 20","10 20"], answer:0, why:"a.limit = 5 creates an instance attribute in a's own dict, which lookup finds before the class. b has no instance attribute, so b.limit falls through to the class, now 20. Assigning through an instance never changes the class attribute."},
 {id:"p4m7q5", q:"fee(miles) returned miles * 2 and had one test, assert fee(2) == 4. Someone changed it to return miles + 2. Which added test catches the regression?", options:["assert fee(2) == 4","assert fee(2) > 0","assert fee(5) == 10","assert isinstance(fee(2), int)"], answer:2, why:"At miles = 2 the wrong formula agrees with the right one (2 + 2 = 2 × 2), so any test sampling only that point still passes. fee(5) should be 10, but the broken version returns 7. Test more than one point, especially edges and boundaries."}
],
"p4m8":[
 {id:"p4m8q1", q:"tool.py calls logging.info('start'), logging.warning('3 lines skipped') and print(result), with no logging configuration. You run python tool.py > out.txt. What ends up where?", options:["out.txt holds the result and both log lines, and the terminal shows nothing at all","out.txt gets the result; the warning shows on screen; the info message is simply dropped","out.txt holds the result and the warning; the info message goes to the terminal","Both log messages go to the terminal, because logging defaults to the DEBUG level"], answer:1, why:"The root logger defaults to WARNING, so the info record is dropped until basicConfig(level=logging.INFO). Log records go to stderr, which > does not redirect, so the warning reaches the screen while print's stdout goes into the file."},
 {id:"p4m8q2", q:"pyproject.toml declares the dependency requests~=2.31. Which of these versions satisfies it?", options:["2.32.3","2.30.1","3.0.0","1.31.0"], answer:0, why:"~=2.31 is the compatible-release specifier: at least 2.31 and still 2.*. 2.32.3 qualifies. 2.30.1 is below the floor, and 3.0.0 leaves the 2.x series, which is exactly what ~= guards against: a major release that may change the API."},
 {id:"p4m8q3", q:"A script dies with a traceback ending in ZeroDivisionError inside a helper function. You want to inspect that frame's variables and its caller's without editing the code. What do you run?", options:["PYTHONBREAKPOINT=0 python script.py, which stops at the line that raised","python -O script.py, so the optimizer prints every local value as it fails","pytest --lf script.py, which reruns the last failure inside a debugger","python -m pdb -c continue script.py, then p and u at the crash"], answer:3, why:"With -c continue, pdb runs the program until the uncaught exception and stops in the crashing frame: post-mortem debugging. p expr prints values and u moves up to the caller. PYTHONBREAKPOINT=0 disables breakpoints, and -O removes asserts rather than adding information."},
 {id:"p4m8q4", q:"tests/test_core.py contains test_parse, test_reject, and one function decorated with @pytest.mark.parametrize over four (input, expected) rows. Everything passes. What does pytest -q report?", options:["3 passed","4 passed","6 passed","7 passed"], answer:2, why:"parametrize turns one function into one test per row, so the decorated function counts as four tests; with the two plain functions that is 6. Counting functions gives 3, and counting the decorated function on top of its rows gives 7."},
 {id:"p4m8q5", q:"A commit from two days ago, a1b2c3d, broke parsing. Three commits have been made since, and the branch is already pushed to GitHub. What is the safe way to undo just that change?", options:["git revert a1b2c3d","git restore core.py","git restore --staged core.py","Delete .git, run git init and commit the current files"], answer:0, why:"git revert makes a new commit that inverts the bad one and keeps history intact for anyone who already pulled. git restore resets working files to the last commit and --staged only unstages, so neither undoes a past commit. Re-initializing destroys all history."}
]
});
